import {advancedQuestion} from './advanced-author';
import type {SourceRow} from './source-author';

const EDITION='Chirurgie generală și specialități chirurgicale, ediția pentru rezidențiat MG 2025';
const pdfOffset=(p:number)=>p===605?p-327:p===606?p-329:p-328;
const q=(n:number,row:SourceRow,score:number,reason:string,expressions:string[],related:number[]=[])=>
 advancedQuestion('ortopedie',28,pdfOffset,`ortopedie-adv-${String(n).padStart(3,'0')}`,row,[score,reason],expressions,undefined,related,'Lawrence',EDITION);

export const ORTOPEDIE_ADVANCED=[
q(1,['Fractura, subluxația și luxația se definesc astfel:',
 ['Fractura este o întrerupere sau o pierdere a continuității structurale a unui os','În subluxație, suprafețele articulare juxtapuse sunt parțial lipsite de contact','În luxație, suprafețele articulare sunt total lipsite de contact','Subluxația articulară nu poate fi tranzitorie și nu se reduce spontan','Luxația reprezintă o deplasare parțială, iar subluxația una completă'],'ABC',585,'Traumatismele — Fracturi, subluxații și luxații',
 'Diferențierea întreruperii osoase de deplasarea parțială versus completă a suprafețelor articulare.',
 ['Definiția fracturii ca întrerupere sau pierdere a continuității osoase este explicită.','Textul descrie subluxația ca lipsă parțială de contact a suprafețelor juxtapuse.','Luxația este definită prin lipsa totală de contact.','Subluxația poate fi tranzitorie, cu reducere spontană.','Raportul este invers: subluxația este parțială, luxația este completă.']],
 8,'Inversează deplasarea parțială/completă, o confuzie clasică de nomenclatură.',['pierdere a continuităţii','total lipsite de contact']),

q(2,['Care dintre următoarele afirmații privind impactul patologiilor musculoscheletale sunt adevărate?',
 ['Patologiile musculoscheletale sunt a doua cea mai frecventă cauză de prezentare la medic','Patruzeci la sută dintre prezentările de la camera de gardă sunt asociate afecțiunilor musculo-scheletale','Dorsalgia este cea mai frecventă cauză de absenteism și de dizabilitate la pacienții sub 45 de ani','Osteoporoza afectează sub 2 milioane de femei aflate la postmenopauză','Sistemul musculoscheletal reprezintă sub 10% din masa totală a corpului'],'ABC',585,'Sistemul musculoscheletal — Impact epidemiologic',
 'Recunoașterea ponderii prezentărilor, a camerei de gardă și a dorsalgiei ca principală cauză de absenteism sub 45 de ani.',
 ['Locul doi al prezentărilor la medic este citat explicit.','Procentul de 40% la camera de gardă este enunțat.','Dorsalgia ca principală cauză de absenteism sub 45 de ani este explicită.','Textul estimează osteoporoza la peste 20 de milioane de femei postmenopauză.','Oasele, articulațiile, mușchii, tendoanele, ligamentele și fascia reprezintă 70% din masa corporală.']],
 8,'Înlocuiește pragurile 20 de milioane și 70% cu valori subestimate din aceeași pagină.',['Patruzeci la sută','Dorsalgia este cea mai frecventă']),

q(3,['Alegeți afirmațiile corecte referitoare la fracturile deschise:',
 ['O fractură este deschisă când o leziune a tegumentului sau a mucoasei permite comunicarea cu mediul extern','Fracturile pelvine pot comunica cu rectul sau vaginul și sunt descoperite doar la un examen fizic amănunțit','Prin definiție, fracturile deschise sunt contaminate și necesită tratament de urgență pentru a preveni infecția','O fractură este deschisă numai dacă linia de fractură este vizibilă la inspecție','Fractura închisă presupune discontinuitate tegumentară, dar fără contaminare bacteriană'],'ABC',586,'Fracturile — Tip: deschisă versus închisă',
 'Recunoașterea comunicării cu mediul extern, inclusiv pe cale pelvină ocultă, ca definiție a fracturii deschise contaminate.',
 ['Definiția prin leziune tegumentară sau mucoasă cu comunicare externă este explicită.','Comunicarea pelvină cu rectul sau vaginul este menționată ca descoperire la examen amănunțit.','Contaminarea prin definiție și urgența tratamentului sunt enunțate.','Unele fracturi deschise, precum cele pelvine, nu sunt evidente la inspecție.','Fractura închisă are pielea sau mucoasa supraiacentă intactă.']],
 8,'Distractorii cer vizibilitate la inspecție și inversează definiția fracturii închise.',['deschise sunt contaminate','microfracturi']),

q(4,['Selectați enunțurile adevărate despre fractura de stres, fractura pe os patologic și localizare:',
 ['Stresul submaximal repetat poate produce microfracturi care, netratate, conduc la fractură de stres','Fractura pe os patologic apare după o traumă minimă pe os anormal, inclusiv osteoporoză sau tumori','Fracturile metafizare, cu aport sanguin bogat, se vindecă de obicei mai repede decât cele diafizare corticale','Fractura de stres este tipică numai osului tumoral, nu soldaților sau antrenamentului intens','Vindecarea diafizară este mai rapidă decât cea metafizară, deci nu necesită protecție prelungită'],'ABC',586,'Fracturile — Stres, os patologic și localizare',
 'Diferențierea fracturii de stres de cea pe os patologic și a ritmului de vindecare metafizar versus diafizar.',
 ['Mecanismul microfracturilor prin stres submaximal repetat este descris.','Definiția pe os patologic, cu osteoporoză și tumori, este explicită.','Vindecarea mai rapidă a osului metafizar/spongios față de corticala diafizară este enunțată.','Fracturile de stres sunt frecvente la soldați și la antrenament intens pe condiție precară.','Fracturile diafizare se vindecă mai lent și cer perioade mai lungi de protecție.']],
 8,'Inversează sediul predilect al stresului și ritmul de vindecare metafiză/diafiză.',['de stres sunt frecvent','os patologic']),

q(5,['Identificați afirmația corectă referitoare la traiectul unei fracturi transversale:',
 ['Apare în urma unui traumatism cu energie redusă, de obicei prin lovitură directă sau avulsie ligamentară','Rezultă tipic din torsiune de mare energie și are tendință minimă de deplasare','Definește orice fractură cu peste două fragmente, denumită și cominutivă','Este traiectul caracteristic al fracturilor intra-articulare ale platoului tibial','Indică absorbția unei energii cinetice maxime, similar fracturii segmentare'],'A',586,'Traiectul fracturii — Transversală versus spiroidă',
 'Recunoașterea fracturii transversale ca leziune de energie redusă, distinctă de spiroidă de torsiune.',
 ['Textul leagă traiectul transversal de energia redusă, lovitura directă sau avulsia ligamentară.','Torsiunea produce fracturi spiroide sau oblice, care tind să se deplaseze și să se scurteze.','Peste două fragmente definesc fractura cominutivă, nu pe cea transversală.','Platoul tibial este citat la fractura impactată, nu ca sediu al traiectului transversal.','Energia mare caracterizează fracturile cominutive, nu transversale.']],
 8,'Mută traiectul transversal către torsiune sau cominuție, două tipare învecinate din aceeași pagină.',['fractură transversală','energie redusă']),

q(6,['Clasificarea Salter-Harris a decolărilor epifizare:',
 ['Tipul I presupune separarea epifizei de metafiză; dacă periostul este intact, fractura rămâne nedeplasată','Tipul III se extinde de la cartilajul de creștere prin epifiză, este intra-articular și necesită reducere perfectă','Tipul IV trece din metafiză prin placa de creștere în epifiză și trebuie fixat chirurgical','Tipul V este cel mai ușor de recunoscut pe radiografia inițială, ca o linie metafizară triunghiulară','Urmărirea radiografică a fracturilor plăcii de creștere se încheie la 6 săptămâni'],'ABC',588,'Clasificarea Salter-Harris a decolărilor epifizare',
 'Aplicarea tipurilor I, III și IV și a implicațiilor de reducere, fixare și prognostic, față de tipul V occult.',
 ['Separarea epifiză-metafiză și rolul periostului în nedeplasare sunt explicite.','Caracterul intra-articular al tipului III și cerința reducerii perfecte sunt enunțate.','Traiectul IV și indicația de fixare chirurgicală pentru a preveni pseudartroza sunt descrise.','Tipul V poate să nu fie aparent pe radiografii și este greu de identificat prospectiv.','Toate fracturile plăcii de creștere se investighează radiografic cel puțin la 1 an.']],
 9,'Confundă tipul V occult cu fragmentul metafizar al tipului II și scurtează urmărirea de la 1 an la 6 săptămâni.',['Salter-Harris de tip I','placa de creştere']),

q(7,['Precizați enunțul corect privind termenii varus și valgus:',
 ['Varus descrie vârful angulării îndreptat opus liniei mediane; genu varum corespunde picioarelor în paranteză','Valgus descrie vârful angulării îndreptat opus liniei mediane; genu valgum corespunde picioarelor în paranteză','Rotația se cuantifică în procente pe radiografia unică de față, nu clinic','Apoziția se exprimă în grade, iar angulația în centimetri','Genu valgum denumește picioarele în paranteză, iar genu varum picioarele în X'],'A',588,'Deplasarea — Varus, valgus, apoziție și rotație',
 'Diferențierea varus/valgus după direcția vârfului angulării față de linia mediană.',
 ['Direcția opusă liniei mediane definește varus; genu varum sunt picioarele în paranteză.','Valgus are vârful către linia mediană; picioarele în X sunt genu valgum.','Rotația se diagnostichează cel mai bine clinic, nu pe o singură radiografie de față.','Apoziția se cuantifică în procente, angulația în grade, scurtarea în centimetri.','Raportul paranteză/X este inversat față de text.']],
 8,'Oglindește varus și valgus, confuzia clasică paranteză versus X.',['genu varum','genu valgum']),

q(8,['Următoarele afirmații despre evaluarea radiologică a traumatismului musculoscheletal sunt adevărate:',
 ['Sunt necesare două incidențe în unghi drept, de obicei anteroposterioară și laterală','Trebuie vizualizată atât articulația proximală, cât și cea distală față de zona lezată','Radiografiile coloanei cervicale sunt indicate la pacienții cu leziuni faciale și la nivelul capului','O singură incidență AP este suficientă pentru cuantificarea deplasării tridimensionale','Fractura de scafoid, dacă nu este evidentă radiografic, se lasă nemobilizată până la CT'],'ABC',588,'Evaluarea pacienților cu traumatism musculoscheletal',
 'Aplicarea regulilor celor două incidențe, a articulațiilor adiacente și a asocierilor (cervical, scafoid).',
 ['Cele două incidențe perpendiculare sunt cerute explicit.','Vizualizarea articulațiilor proximală și distală este al doilea principiu.','Asocierea leziunilor faciale/cap cu radiografii cervicale este enunțată.','O singură incidență nu permite descrierea exactă a deplasării.','Dacă fractura de scafoid este suspectată clinic, se imobilizează și se reevaluează.']],
 8,'Anulează regula celor două incidențe și a imobilizării scafoidului occult.',['două incidenţe','coloanei cervicale'],[590]),

q(9,['Sindromul de embolie grăsoasă după fracturi de oase lungi se caracterizează prin:',
 ['Peteșii asociate cu alterarea stării mentale','Dispnee și saturație scăzută a oxigenului, cu opacifiere difuză pe radiografia toracică, fără leziuni focale','Diagnostic clinic, în absența unei investigații de laborator specifice','Confirmarea prin dozarea trigliceridelor serice înaintea oricărui tratament','Tratamentul de primă intenție este embolectomia chirurgicală a arterei pulmonare'],'ABC',590,'Evaluare — Sindromul de embolie grăsoasă',
 'Recunoașterea triadei clinico-radiologice și a caracterului de diagnostic clinic cu tratament suportiv.',
 ['Asocierea peteșii-alterare mentală este explicită.','Dispneea, hipoxemia și opacifierea difuză fără focare sunt descrise.','Absența unei investigații de laborator specifice este enunțată.','Nu există test de laborator specific; diagnosticul este clinic.','Tratamentul este suportiv și, în cazuri grave, intubație cu oxigen până la 100%.']],
 8,'Transformă un diagnostic clinic suportiv într-unul de laborator sau chirurgical.',['embolie grăsoasă','opacifiere difuză']),

q(10,['Montarea corectă a atelei la un pacient cu fractură presupune:',
 ['Imobilizarea atât a articulației supraiacente, cât și a celei subiacente focarului de fractură','Imobilizarea doar a focarului, lăsând articulațiile adiacente libere pentru a preveni redoarea','Aplicarea tracțiunii transosoase înaintea oricărei atele, la toate fracturile de antebraț','Verificarea neurovasculară o singură dată, înainte de montarea atelei, fără reevaluare','Lăsarea fracturilor deschise fără atelă, pentru a nu închide contaminarea'],'A',590,'Principii de tratament — Imobilizarea în atelă',
 'Recunoașterea imobilizării articulațiilor de deasupra și de dedesubt ca regulă a atelei corecte.',
 ['Textul cere imobilizarea articulației supraiacente și a celei subiacente.','Atelele trebuie să cuprindă articulațiile adiacente, nu doar focarul.','Tracțiunea transosoasă nu este pasul inițial al tuturor fracturilor de antebraț.','Examenul neurovascular se repetă după orice reducere sau manipulare.','Toate traumatismele musculo-scheletale se imobilizează în atele, inclusiv cele deschise.']],
 8,'Omite articulațiile adiacente, o eroare practică frecventă de imobilizare.',['Montarea corectă','subiacente focarului']),

q(11,['În tratamentul inițial al fracturii deschise se recomandă:',
 ['Examinarea leziunii o singură dată, acoperirea cu pansament steril și imobilizarea în atelă','Administrarea de vaccin antitetanic, dacă este necesar, și inițierea antibioticelor','Pentru leziunile ușor contaminate, cefalosporine de generația I intravenos','Debridarea și irigarea se fac de rutină la pat, fără anestezie, înaintea oricărui pansament','Tratamentul fracturii se finalizează înainte de obținerea unei plăgi aseptice'],'ABC',591,'Fracturi deschise — Debridare și antibiotice',
 'Aplicarea secvenței examen unic-pansament-atelă, a antitetanosului și a cefalosporinei de generația I la contaminare ușoară.',
 ['Examenul unic, pansamentul steril și atela sunt descrise.','Antitetanosul și antibioticele sunt cerute.','Cefalosporinele de generația I intravenos sunt indicate la contaminare ușoară.','Debridarea și irigarea se fac de obicei în sala de operație, sub anestezie generală.','Tratamentul fracturii nu se realizează până nu se obține o plagă aseptică.']],
 8,'Inversează locul debridării (sala versus pat) și ordinea plagă aseptică/osteosinteză.',['cefalosporine de generaţia I','pansament steril']),

q(12,['Formarea calusului moale în etapele vindecării fracturii corespunde intervalului:',
 ['2 zile–6 săptămâni, cu proliferare de condroblaste și osteoblaste și os imatur sau fibros','Imediat după traumatism, concomitent cu formarea hematomului','10 zile–4 luni, etapă de consolidare cu os lamelar','2–24 luni, de remodelare și reconstituire a cavității medulare','Ore până la săptămâni, limitat la inflamație fără proliferare celulară'],'A',591,'Etapele vindecării fracturii — Tabelul 28-1',
 'Plasarea calusului moale între hematom/inflamație și calusul dur, cu intervalul 2 zile–6 săptămâni.',
 ['Tabelul atribuie calusului moale intervalul 2 zile–6 săptămâni și osul fibros.','Hematomul se formează imediat, distinct de calusul moale.','Calusul dur (consolidare, os lamelar) este 10 zile–4 luni.','Remodelarea este 2–24 luni.','Inflamația și proliferarea celulară ocupă ore până la săptămâni, înaintea calusului moale.']],
 8,'Permutează intervalele tabelului 28-1 între calus moale, calus dur și remodelare.',['calusului moale','2 zile - 6 săptămâni']),

q(13,['Indicațiile reducerii deschise a unei fracturi includ:',
 ['Eșecul metodelor de reducere închisă','Fracturile cu traiect intra-articular, pentru reconstituirea perfectă a suprafeței articulare','Reducerea deschisă ca primă intenție a oricărei fracturi transversale de ulnă, fără tentativă închisă','Menținerea alinierii doar prin gravitație, fără nicio formă de imobilizare','Interzicerea reducerii închise la copii, inclusiv a tracțiunii transtegumentare'],'AB',591,'Reducerea — Închisă versus deschisă',
 'Recunoașterea eșecului reducerii închise și a fracturilor intra-articulare ca indicații de reducere deschisă.',
 ['Eșecul reducerii închise este prima indicație enunțată.','Fracturile intra-articulare cer reconstituire perfectă pentru a împiedica artroza.','Reducerea închisă este metoda inițială; transversala de ulnă nu este indicație de deschidere primară.','Menținerea reducerii necesită imobilizare (gips, tracțiune, orteză, fixare).','Tracțiunea transtegumentară este utilă la copiii mici.']],
 8,'Extinde reducerea deschisă la toate transversalele și anulează tracțiunea pediatrică.',['reducerea deschisă','intra-articular']),

q(14,['Indicațiile pentru fixarea internă a unei fracturi, conform tabelului 28-2, includ:',
 ['Eșecul metodelor non-operatorii de reducere','Reducerea anatomică a fracturilor intra-articulare','Fracturi la care nu se poate aplica tracțiune sau gips, de exemplu col femural sau intertrohanteriene la vârstnici','Fracturi deschise contaminate, pentru a evita debridarea repetată','Fracturi infectate, ca metodă de elecție în locul fixatorului extern'],'ABC',594,'Fixarea internă — Tabelul 28-2',
 'Aplicarea indicațiilor de osteosinteză internă, distincte de cele ale fixatorului extern (deschise, infectate).',
 ['Eșecul non-operator este prima indicație din tabel.','Reducerea anatomică intra-articulară figurează explicit.','Colul femural și fracturile intertrohanteriene la vârstnici sunt exemplele din tabel.','Fracturile deschise instabile sunt indicație de fixare externă, nu internă de primă intenție.','Fracturile infectate figurează la indicațiile fixării externe.']],
 8,'Mută indicațiile tabelului 28-3 (deschise, infectate) asupra fixării interne.',['fixarea internă','colului femural']),

q(15,['Fixarea externă a unei fracturi este indicată în:',
 ['Fracturi deschise instabile, pentru accesul la plagă și evitarea implantului intern în contaminare','Fracturi pelvine instabile','Fracturi închise nedeplasate de radius distal, ca tratament de primă intenție la vârstnici','Fracturi de scafoid nedeplasate, în locul atelei gipsate','Orice fractură metafizară impactată, pentru a accelera vindecarea spongioasă'],'AB',594,'Fixarea externă — Tabelul 28-3',
 'Recunoașterea fracturilor deschise instabile și pelvine instabile ca indicații clasice de fixator extern.',
 ['Accesul la leziune și evitarea implantului intern în plagă contaminată sunt explicite.','Fracturile pelvine instabile figurează în tabel.','Colles nedeplasat nu este indicație de fixator ca primă intenție.','Scafoidul nedeplasat se imobilizează în atelă gipsată.','Osul metafizar impactat se vindecă adesea fără fixator extern.']],
 8,'Extinde fixatorul extern la Colles și scafoid nedeplasat, tratate de fapt conservator.',['Fracturi deschise, instabile','Fracturi pelvine instabile']),

q(16,['Complicațiile locale ale vindecării fracturii includ:',
 ['Întârzierea în consolidare, când perioada de vindecare depășește pe cea fiziologică','Pseudartroza, cu țesut fibros sau membrană sinovială între fragmente dacă mobilizarea este excesivă','Calusul vicios, cu scurtare, angulare sau rotație, care poate impune osteotomie de corecție','Embolia grăsoasă și tetanosul, ca manifestări strict locale ale focarului','Artroza post-traumatică apare doar după fracturi extra-articulare perfect reduse'],'ABC',594,'Complicații locale — Consolidare, pseudartroză, calus vicios',
 'Diferențierea întârzierii, pseudartrozei și calusului vicios de complicațiile sistemice și de artroza intra-articulară.',
 ['Definiția întârzierii față de perioada fiziologică este explicită.','Pseudartroza cu țesut fibros sau articulație falsă este descrisă.','Calusul vicios și indicația de osteotomie sunt enunțate.','Embolia grăsoasă și tetanosul sunt complicații sistemice, nu locale.','Artroza post-traumatică urmează fracturilor intra-articulare cu deplasare.']],
 8,'Clasifică greșit embolia/tetanosul ca locale și inversează sediul artrozei post-traumatice.',['Întârzierea în consolidare','Calusul vicios']),

q(17,['Oasele cele mai vulnerabile la osteonecroză post-traumatică, prin acoperire cartilaginoasă extinsă și înveliș muscular slab, sunt:',
 ['Capul femural, scafoidul și talusul','Diafiza femurală, ulna și calcaneul','Metacarpianul V, olecranul și platoul tibial','Coastele, sternul și clavicula medială','Peroneul distal, cuboidul și pisiformul'],'A',594,'Necroza avasculară post-traumatică',
 'Identificarea capului femural, scafoidului și talusului ca oase cu risc înalt de osteonecroză.',
 ['Cele trei oase sunt enumerate explicit ca vulnerabile.','Diafiza femurală are înveliș muscular bogat și nu figurează pe listă.','Olecranul și platoul tibial nu sunt citate ca sedii clasice de osteonecroză în acest paragraf.','Coastele și sternul nu apar în lista de vulnerabilitate.','Oasele mici menționate nu sunt cele trei exemple ale textului.']],
 8,'Înlocuiește triada cap femural-scafoid-talus cu oase vecine din același capitol.',['capul femural','osul scafoid']),

q(18,['Scurtarea membrului inferior după leziunea cartilajului de creștere la copil:',
 ['O scurtare sub 1 cm este bine tolerată','Scurtarea de 1–2 cm se rezolvă cu pantofi cu talpă groasă','O scurtare peste 2 cm se corectează prin epifiziodeză contralaterală','Orice scurtare, inclusiv de 5 mm, impune alungire chirurgicală imediată','Diformitatea angulară prin afectare parțială nu beneficiază de chirurgie, chiar precoce'],'ABC',594,'Tulburările de creștere — Scurtare și epifiziodeză',
 'Aplicarea pragurilor sub 1 cm, 1–2 cm (talpă) și peste 2 cm (epifiziodeză contralaterală).',
 ['Toleranța sub 1 cm este explicită.','Soluția cu talpă groasă pentru 1–2 cm este citată.','Epifiziodeza contralaterală pentru scurtare peste 2 cm este enunțată.','Scurtarea de 5 mm este bine tolerată, nu impune alungire.','Diformitatea angulară prin afectare parțială se tratează chirurgical cu rezultate bune dacă este precoce.']],
 8,'Permutează pragurile 1 cm și 2 cm și anulează osteotomia precoce a deformării angulare.',['talpă groasă','epifiziodeză']),

q(19,['În luxația posterioară de șold, membrul afectat este poziționat tipic în:',
 ['Flexie, adducție și rotație internă','Extensie, abducție și rotație externă','Flexie, abducție și rotație externă, ca în fractura de col femural','Extensie, adducție și rotație externă','Flexie neutră fără rotație, cu sprijin permis pe membru'],'A',595,'Subluxația și luxația articulară — Poziția membrului',
 'Recunoașterea triadei flexie-adducție-rotație internă ca poziție clasică a luxației posterioare de șold.',
 ['Poziția de flexie, adducție și rotație internă este enunțată explicit.','Extensia, abducția și rotația externă descriu alt pattern, nu luxația posterioară.','Rotația externă și scurtarea sunt tipice fracturilor de șold, nu luxației posterioare.','Combinația extensie-adducție-rotație externă nu este descrisă.','Pacientul evită mișcarea articulației luxate; sprijinul nu este permis.']],
 8,'Înlocuiește triada posterioară cu rotația externă a fracturii de șold, două entități învecinate.',['luxat posterior','rotaţie internă']),

q(20,['Un tânăr cade pe mâna în hiperextensie, cu pumnul în flexie dorsală și deviere radială, și are sensibilitate în tabachera anatomică. Sunt adevărate:',
 ['Scafoidul este osul cel mai frecvent fracturat dintre oasele carpiene','Pacientul trebuie tratat ca pentru o fractură dovedită, chiar dacă radiografia inițială nu arată linie de fractură','Fracturile nedeplasate se imobilizează într-o atelă gipsată care încorporează antebrațul în extensie și policele în abducție','Fracturile nedeplasate se lasă fără imobilizare, urmărirea fiind doar clinică la 6 luni','Necroza avasculară este rară, deoarece scafoidul are vascularizație abundantă și nu este acoperit de cartilaj'],'ABC',595,'Leziuni frecvente — Fractura osului scafoid',
 'Aplicarea mecanismului FOOSH, a regulii tabacherei anatomice și a imobilizării nedeplasate, față de riscul de osteonecroză.',
 ['Frecvența maximă între oasele carpiene este explicită.','Tratamentul ca fractură dovedită, chiar cu radiografie negativă, este cerut.','Atela cu antebraț în extensie și police în abducție este descrisă pentru nedeplasate.','Nedeplasatele se imobilizează, nu se lasă libere.','Scafoidul este acoperit de cartilaj hialin, cu vascularizație limitată, deci NAV și pseudartroză sunt frecvente.']],
 8,'Omite imobilizarea scafoidului occult și neagă riscul de osteonecroză.',['tabachera anatomică','flexie dorsală']),

q(21,['Fractura Colles a radiusului distal:',
 ['Este o fractură transversală imediat proximal de articulația pumnului, după cădere pe mâna în hiperextensie','Este frecventă la vârstnici sau cu osteoporoză; radiografic există cominuție dorsală, impactare și angulare palmară','După reducere, o atelă se aplică de la cot până la palmă, cu radiografie de control la 10 zile','Reducerea se obține prin dorsiflexia accentuată a pumnului și deviație radială','Nervul ulnar este structura de examinat înainte și după reducere, nu nervul median'],'ABC',595,'Fractura distală de radius — Colles',
 'Recunoașterea mecanismului, a aspectului radiografic și a atelei cot-palmă cu control la 10 zile.',
 ['Definiția transversală imediat proximal de pumn și mecanismul sunt explicite.','Asocierea cu osteoporoza, cominuția dorsală și angularea palmară sunt descrise.','Atela de la cot la palmă și radiografia la 10 zile figurează pe pagina următoare.','Reducerea pune pumnul în flexie și deviație ulnară, nu în dorsiflexie și deviație radială.','Nervul median, aflat pe fața volară, trebuie examinat înainte și după reducere.']],
 8,'Inversează flexia/deviația ulnară a reducerii și nervul median cu ulnarul.',['fractură Colles','angulare palmară'],[596]),

q(22,['Pronația dureroasă a cotului la copilul de 1–4 ani, după ce a fost tras de mână, se tratează prin:',
 ['Flexie ușoară a cotului și supinația mâinii, cu repoziționarea ligamentului inelar în jurul colului radial','Imobilizare gipsată în pronație forțată timp de 6 săptămâni','Fixare percutanată cu broșe a colului radial, similar fracturii supracondiliene','Tracțiune transosoasă prin olecran, ca în fracturile de humerus','Artrotomie de urgență pentru a exclude artrita septică a cotului'],'A',596,'Pronația dureroasă a cotului',
 'Recunoașterea manevrei de flexie ușoară plus supinație ca tratament al subluxației ligamentului inelar.',
 ['Manevra de flexie ușoară și supinație, cu repoziționarea ligamentului inelar, este explicită.','Nu se descrie gips în pronație forțată.','Broșele percutanate privesc fractura supracondiliană, nu pronația dureroasă.','Tracțiunea prin olecran nu este tratamentul acestei entități.','Artrita septică nu este diagnosticul acestei leziuni de ligament inelar.']],
 8,'Înlocuiește manevra simplă de supinație cu osteosinteza supracondiliană învecinată.',['ligamentului inelar','colului radial']),

q(23,['Un copil de 7 ani cade pe mâna hiperextinsă, cu cotul extins. Fractura supracondiliană de humerus:',
 ['Fragmentul distal este deplasat adesea posterior','Poate leza artera brahială și nervii median și radial, la producere sau la reducere','Este o cauză frecventă de sindrom de compartiment (contractură ischemică Volkmann)','Ischemia musculară peste 2 ore, la temperatură corporală normală, produce leziuni musculare permanente','Prezența pulsului radial exclude sindromul de compartiment al antebrațului'],'ABCD',596,'Fractura supracondiliană a humerusului — Volkmann',
 'Integrarea deplasării posterioare, a leziunii neurovasculare, a Volkmann și a pragului de 2 ore, față de falsul reconfort al pulsului.',
 ['Deplasarea posterioară a fragmentului distal este enunțată.','Artera brahială, nervul median și radialul sunt citate.','Asocierea cu contractura ischemică Volkmann este explicită.','Pragul de peste 2 ore pentru leziuni musculare permanente este descris.','Sindromul de compartiment poate exista cu puls și sensibilitate normale.']],
 9,'Pragul de 2 ore și falsul reconfort al pulsului sunt near-miss-uri clasice de compartiment.',['contractură ischemică Volkmann','Artera brahială'],[600]),

q(24,['Luxația umărului se caracterizează prin:',
 ['Umărul este articulația care se luxează cel mai frecvent; în peste 90% din luxațiile traumatice capul humeral este anterior','Integritatea nervului axilar se testează prin sensibilitatea regiunii deltoidiene și funcția motorie a deltoidului, înainte și după reducere','Luxația posterioară trebuie suspectată după electrocutare, criză epileptică sau sevraj alcoolic','Luxația posterioară se exclude pe o singură radiografie AP, în care capul pare aliniat cu glena','Reducerea se obține prin adducție forțată și rotație internă maximă, fără tracțiune'],'ABC',596,'Luxația umărului — Anterioară versus posterioară',
 'Recunoașterea predominanței anterioare, a nervului axilar și a contextului posterioarei omise pe AP.',
 ['Frecvența maximă și deplasarea anterioară în peste 90% sunt explicite.','Testarea nervului axilar înainte și după reducere este cerută.','Contextul electrocutare/epilepsie/sevraj este enunțat.','Posterioara este frecvent omisă pe AP; este necesară incidența axilară.','Reducerea anterioarei se face prin abducție graduală cu tracțiune și contratracție în axilă.']],
 8,'Tratează radiografia AP ca suficientă pentru posterioară și inversează manevra de reducere.',['90% din luxaţiile traumatice','nervul axillar'],[597]),

q(25,['Fractura de col femural se deosebește de cea intertrohanterică prin:',
 ['Este intracapsulară, cu periost subțire și fără înveliș muscular, deci cu risc înalt de pseudartroză','Vasele capului femural, pe fața posterioară a colului, pot fi lezate, cu necroză a capului','Fractura intertrohanterică este extracapsulară, cu vascularizație bună și vindecare obișnuită','Ambele sunt extracapsulare, cu risc identic de necroză a capului femural','Fixarea cu șurub de glisare și placă este tratamentul colului, nu al fracturii intertrohanterice'],'ABC',598,'Fracturile șoldului — Col femural versus intertrohanterică',
 'Contrastarea sediului intracapsular (NAV, pseudartroză) cu cel extracapsular intertrohanteric (vindecare, DHS).',
 ['Caracterul intracapsular, periostul subțire și absența mușchiului explică pseudartroza.','Traiectul posterior al vaselor și riscul de necroză sunt descrise.','Sediul extracapsular și vindecarea intertrohantericei sunt explicite.','Doar colul este intracapsular; intertrohanterica este extracapsulară.','Șurubul de glisare cu placă tratează intertrohanterica; colul se fixează sau se înlocuiește prin hemiartroplastie.']],
 8,'Oglindește intra- versus extracapsular și atribuie DHS-ul colului, nu intertrohantericei.',['colului femoral','intertrohanterice']),

q(26,['Pierderea sanguină estimată într-o fractură închisă de diafiză femurală este de:',
 ['1–3 unități de sânge la nivelul coapsei, cu risc de șoc hipovolemic','Sub 200 mL, insuficientă pentru a produce hipovolemie','Peste 8 unități, ceea ce impune toracotomie de control','Nicio pierdere semnificativă, osul cortical fiind avascular','Echivalentul unei fracturi de scafoid, deci fără nevoie de radiografii de pelvis'],'A',598,'Fracturile diafizei femurale — Pierdere sanguină',
 'Recunoașterea intervalului 1–3 unități și a riscului de șoc, cu excluderea altor surse de hipovolemie.',
 ['Intervalul 1–3 unități cu posibil șoc hipovolemic este explicit.','Pierderea este considerabilă, nu minimă.','Toracotomia nu figurează ca tratament al fracturii femurale.','Osul cortical are aport, iar hematoma coapsei este voluminoasă.','Radiografiile de pelvis și șold sunt cerute la toți pacienții cu fractură de femur.']],
 8,'Înlocuiește intervalul 1–3 unități cu volume din alte leziuni (hemotorax, scafoid).',['1-3 unităţi de sânge','hipovolemie']),

q(27,['Luxația posterioară de șold după impactul genunchiului de bord:',
 ['Poate produce elongația nervului sciatic; pacienții trebuie evaluați pentru mers stepat','Orice întârziere a reducerii peste 8–12 ore crește riscul de necroză avasculară a capului femural și de artroză post-traumatică','Reducerea poate fi amânată 48 de ore fără risc suplimentar de osteonecroză','Nervul femural, nu sciaticul, este structura neurologică amenințată','Mersul stepat sugerează leziunea nervului axilar, nu a sciaticului'],'AB',598,'Luxația șoldului — Sciatic și fereastra 8–12 ore',
 'Aplicarea evaluării sciaticului (mers stepat) și a ferestrei de 8–12 ore pentru osteonecroză.',
 ['Elongația sciaticului și mersul stepat sunt explicite.','Fereastra de peste 8–12 ore pentru NAV și artroză este citată.','Întârzierea crește riscul; amânarea 48 de ore nu este sigură.','Nervul amenințat este sciaticul, nu femuralul.','Mersul stepat este atribuit sciaticului, nu nervului axilar (deltoid).']],
 8,'Scurtează sau anulează fereastra 8–12 ore și schimbă sciaticul cu femuralul sau axilarul.',['8-12 ore','nervului sciatic']),

q(28,['Fracturile diafizare de tibie se caracterizează prin:',
 ['Se produc de 9 ori mai frecvent decât cele de diafiză femurală; aproape 33% din suprafața tibiei este subcutanată','Au risc crescut de sindrom de compartiment; semnul cardinal la conștient este durerea disproporționată','Osteosinteza pe focar închis și gipsul deasupra genunchiului sunt tratamentul standard al fracturilor închise necomplicate','Vascularizația abundantă a tibiei face pseudartroza excepțională','Fixatorul extern este contraindicated în fracturile deschise de tibie, fiind rezervat colului femural'],'ABC',598,'Fracturile diafizelor tibială și fibulară',
 'Integrarea frecvenței, a sediului subcutanat, a compartimentului și a gipsului deasupra genunchiului.',
 ['Raportul 9:1 față de femural și cei 33% subcutanat sunt explicite.','Riscul de compartiment și durerea disproporționată sunt enunțate.','Standardul pentru închise necomplicate este osteosinteza închisă și gipsul deasupra genunchiului.','Vascularizația redusă duce la pseudartroză și întârziere de consolidare.','Fixarea externă este frecvent folosită în fracturile deschise de tibie.']],
 8,'Inversează vascularizația tibiei și contraindică fixatorul extern tocmai acolo unde este clasic.',['de 9 ori','pacient conştient']),

q(29,['O deplasare de 1 mm a unei fracturi de gleznă reduce suprafața de contact articulară cu:',
 ['40%','10%','5%','75%','Nicio reducere a suprafeței, dacă maleola posterioară este intactă'],'A',599,'Leziunile gleznei — Congruență articulară',
 'Memorarea pragului 1 mm = 40% pierdere de contact, care fundamentează reducerea anatomică deschisă.',
 ['Textul precizează că o deplasare de 1 mm reduce suprafața de contact cu 40%.','10% nu este valoarea citată.','5% subestimează pierderea de contact.','75% supraestimează procentul din text.','Principiul vizează congruența articulară independent de maleola posterioară izolată.']],
 8,'Înlocuiește procentul 40% cu valori plauzibile vecine, un near-miss cantitativ.',['I mm reduce','cu 40%']),

q(30,['Fracturile de bazin cu velocitate mare:',
 ['Aproximativ 1 din 5 prezintă concomitent leziuni ale vezicii urinare sau ale uretrei, la bărbați','Sânge la meat sau incapacitatea de a urina impune uretrografie retrogradă înaintea sondei vezicale','Sânge în rect sau vagin face fractura deschisă; după debridare și fixare externă se practică colostomie','Stabilizarea de urgență cu fixator extern este inutilă în instabilitatea hemodinamică','Hematuria se evaluează prin uretrografie, nu prin urografie intravenoasă'],'ABC',599,'Fracturile de bazin — Uretră, vezică și fractură deschisă',
 'Aplicarea ratei 1 din 5 a leziunilor urologice, a uretrografiei înaintea sondei și a colostomiei în fractura pelvină deschisă.',
 ['Proporția 1 din 5 la bărbați este explicită.','Uretrografia retrogradă înaintea cateterului este cerută la sânge pe meat sau anurie.','Sângele rectal/vaginal definește fractura deschisă, tratată și prin colostomie.','Fixatorul extern de urgență este considerat esențial în instabilitate hemodinamică.','Hematuria se evaluează prin urografie intravenoasă, pentru funcția renală.']],
 8,'Inversează uretrografia și urografia și anulează rolul fixatorului în șoc.',['I din 5 fracturi','uretrografie retrogradă']),

q(31,['Reimplantarea după amputație traumatică:',
 ['Cu cât masa musculară a segmentului amputat este mai mare, cu atât prognosticul funcțional este mai rezervat','La adult, nivelele favorabile sunt policele, mai multe degete simultan și zona pumnului sau metacarpiană','Segmentul rămâne viabil circa 6 ore în ischemie caldă (36°C) și până la 16 ore în ischemie rece (10°C)','Pregătirea pentru transport include pansament umed și sac etanș imersat în apă cu gheață','Gheața uscată este metoda de elecție, deoarece scade metabolismul fără risc de degerătură'],'ABCD',600,'Amputația traumatică și reimplantarea',
 'Aplicarea regulii masei musculare, a nivelelor favorabile la adult și a ferestrelor 6/16 ore, față de gheața uscată interzisă.',
 ['Regula masei musculare și a ischemiei este explicită.','Policele, degetele multiple și pumnul/metacarpul sunt nivelele favorabile la adult.','Cele 6 ore la 36°C și 16 ore la 10°C sunt citate.','Pansamentul umed și sacul în apă cu gheață sunt descrise.','Gheața uscată produce degerături și leziuni tisulare suplimentare.']],
 8,'Permutează ferestrele de ischemie și promovează gheața uscată, o eroare de transport.',['6 ore','16 ore de ischemie']),

q(32,['Sindromul de compartiment al membrului:',
 ['Semnele clasice sunt cei patru P: durere, parestezie, paralizie și paloare; durerea este semnul cel mai util','Durerea este intensificată de întinderea pasivă a mușchilor din compartimentul afectat','Poate exista în prezența unui puls și a unei sensibilități normale','Fasciotomia este indicată dacă presiunea depășește 30–40 mm Hg la un pacient inconștient sau cu paralizie','Clinicianul trebuie să aștepte paloarea și paralizia înainte de a îndepărta gipsul circular'],'ABCD',600,'Sindromul de compartiment — Semne și prag de fasciotomie',
 'Integrarea celor 4 P, a durerii la stretch, a pulsului păstrat și a pragului 30–40 mm Hg, față de așteptarea greșită a palorii.',
 ['Cei patru P și caracterul durerii ca semn cel mai util sunt explicite.','Intensificarea la întindere pasivă este descrisă.','Apariția cu puls și sensibilitate normale este enunțată.','Pragul 30–40 mm Hg la inconștient/paralizat figurează pe pagina următoare.','Nu se așteaptă parestezia, paralizia sau paloarea; gipsul circular se îndepărtează la durere disproporționată.']],
 9,'Near-miss pe pragul 30 mm Hg și pe falsul reconfort al pulsului, două erori de compartiment.',['patru P','30 nm1 Hg'],[601]),

q(33,['Fractura de stres:',
 ['Radiografiile au sensibilitate scăzută, cu o rată de rezultate fals-negative de aproximativ 70%','Scintigrafia cu pirofosfat de technetiu poate identifica fracturile de stres în stadii precoce','Radiografia simplă are sensibilitate de peste 95% din prima zi și face scintigrafia inutilă','Tratamentul constă în încărcare imediată pentru a stimula calusul dur','Sunt întâlnite doar la nivelul primului metatarsian, nu la femur, tibie sau coaste'],'AB',601,'Leziuni sportive — Fractura de stres',
 'Recunoașterea fals-negativelor radiografice de 70% și a rolului scintigrafiei cu technetiu.',
 ['Rata de 70% fals-negative radiografice este explicită.','Pirofosfatul de technetiu detectează formarea osoasă precoce.','Radiografia este nesensibilă, nu de 95%.','Tratamentul tradițional este repaus și protecție față de stres.','Au fost identificate la femur, tibie, calcaneu, metatarsiene, humerus, coaste și L5.']],
 8,'Inversează sensibilitatea radiografiei (70% fals-negative) și limitează sediul la metatarsianul de marș.',['fals-negative, de aproximativ 70%','pirofosfat de teclmeţiu']),

q(34,['Coafa rotatorilor a umărului:',
 ['Cei patru mușchi sunt subscapular, supraspinos, infraspinos și rotund mic','Aria în secțiune a coafei este egală cu cea a deltoidului, deci forța de stabilizare egalează forța de mobilitate','Ruptura coafei reduce forța de rotație externă a umărului','Mușchiul principal comprimat sub arcul coraco-acromial în abducție este subscapularul','Diagnosticul de ruptură se pune doar clinic, artrografia, ecografia și IRM-ul fiind inutile'],'ABC',602,'Tendinita coafei rotatorilor',
 'Identificarea celor patru mușchi, a echivalenței de arie cu deltoidul și a deficitului de rotație externă.',
 ['Cei patru mușchi sunt enumerați explicit.','Egalitatea de arie și de forță cu deltoidul este descrisă.','Ruptura reduce forța de rotație externă.','În abducție, supraspinosul se contractă sub arcul coraco-acromial, nu subscapularul.','Artrografia, ecografia sau IRM diagnostichează ruptura cu acuratețe.']],
 8,'Schimbă supraspinosul cu subscapularul sub acromion și neagă imagistica rupturii.',['subscapular, supraspinos','rotaţia externă']),

q(35,['Entorsele ligamentare se clasifică astfel:',
 ['Gradul I: leziuni microscopice cu sensibilitate, fără modificare a stabilității la stres','Gradul III: întrerupere totală cu pierderea stabilității articulației','Gradul I presupune ruptură completă și punct final absent la testare','Gradul II păstrează continuitatea macroscopică, dar nu produce nicio laxitate','Ligamentul deltoid al gleznei este lezat mai frecvent decât ligamentele laterale, deoarece maleola peronieră este scurtă'],'AB',604,'Entorsele — Gradele I–III și gleznă',
 'Diferențierea gradului I (stabil) de III (instabil) și recunoașterea predominanței ligamentelor laterale ale gleznei.',
 ['Gradul I microscopic fără instabilitate este explicit.','Gradul III ca întrerupere totală cu pierderea stabilității este definit.','Ruptura completă definește gradul III, nu I.','Gradul II are laxitate cu punct final ferm.','Maleola peronieră mai lungă protejează împotriva eversiunii; deltoidul este mai rar afectat.']],
 8,'Oglindește gradele I și III și inversează anatomia maleolei peroniere/deltoidului.',['Entorsele de gradul I','entorsă de gradul III']),

q(36,['Ligamentul încrucișat anterior (LIA):',
 ['Este singurul dintre cele patru ligamente majore ale genunchiului care este intrasinovial','Dintre pacienții cu hemartroză după leziuni de genunchi, 70% au leziuni de LIA; la leziunile acute de LIA, 50% asociază leziuni meniscale','LIA se vindecă prost și se reconstruiește, în general, cu autogrefă de țesuturi moi','Leziunile izolate de ligament colateral medial se vindecă prost și impun reconstrucție cu autogrefă de tendon patelar','Testul Lachman, cu genunchiul la 90° de flexie, evaluează fibrele anteromediale ale LIP'],'ABC',606,'Entorsele de genunchi — LIA, hemartroză și reconstrucție',
 'Aplicarea caracterului intrasinovial, a ratelor 70%/50% și a vindecării proaste a LIA, față de LCM izolat.',
 ['Caracterul intrasinovial unic este explicit.','Procentele 70% (hemartroză-LIA) și 50% (menisc) sunt citate.','Vindecarea proastă și autogrefa sunt enunțate.','LCM izolat se vindecă bine cu gips articulat; reconstrucția descrisă este a LIA.','Lachman se face la 20° și evaluează fibrele posterolaterale ale LIA, nu LIP la 90°.']],
 8,'Schimbă LIA cu LCM la indicația de autogrefă și inversează unghiul Lachman.',['70% au leziuni','testul Lachman']),

q(37,['Leziunea meniscală a genunchiului:',
 ['În ortostatism, meniscul distribuie 40–60% din greutatea corpului la nivelul articulației','Rupturile longitudinale din treimea periferică se pot vindeca când sunt reparate, zona fiind bine vascularizată','Meniscectomia totală duce la dezvoltarea lentă a artrozei tibiofemurale','Testul McMurray se efectuează cu genunchiul în extensie completă, fără rotație tibială','Rupturile în mâner de găleată nu produc blocaj mecanic, ci doar durere de repaus nocturn'],'ABC',607,'Leziunea meniscală — Sarcină, vascularizație și McMurray',
 'Recunoașterea distribuției 40–60%, a vindecării periferice și a artrozei după meniscectomie totală.',
 ['Intervalul 40–60% este explicit.','Vindecarea rupturilor longitudinale periferice reparate este descrisă.','Artroza după meniscectomie totală este enunțată.','McMurray implică flexie la 90°, rotație tibială, apoi extensie în valgus sau varus.','Rupturile în mâner de găleată prind fragmentul între condil și platou și blochează mecanic articulația.']],
 8,'Inversează tehnica McMurray (90° plus rotație) și neagă blocajul din mânerul de găleată.',['40-60%','mâner de găleată'],[606]),

q(38,['Disjuncția acromio-claviculară, degetul Mallet și fractura boxerului:',
 ['În disjuncția de gradul III sunt afectate atât ligamentul acromioclavicular, cât și ligamentele coracoclaviculare, cu extremitatea laterală a claviculei ridicată deasupra acromionului','Degetul Mallet se vindecă bine dacă articulația interfalangiană distală este imobilizată în extensie completă timp de 6 săptămâni','Fractura boxerului (metacarpianul V) se tratează de obicei prin reducere închisă și imobilizare gipsată, chiar la angulații peste 45°','Gradul III acromio-clavicular se recunoaște prin subluxație vizibilă doar pe radiografii de stres cu greutăți, clavicula rămânând la nivelul acromionului','Degetul Mallet impune sutura chirurgicală de urgență a tendonului, imobilizarea fiind ineficientă'],'ABC',607,'Leziuni ale umărului și mâinii — AC, Mallet, boxer',
 'Diferențierea gradului III AC (ambele ligamente, claviculă ridicată) de Mallet (6 săptămâni în extensie DIP) și de fractura boxerului tratată conservator.',
 ['Ruptura ambelor ligamente și clavicula ridicată definesc gradul III.','Imobilizarea DIP în extensie 6 săptămâni este tratamentul Mallet.','Reducerea închisă și gipsul, chiar la angulație peste 45°, sunt preferate la boxer.','Radiografiile de stres cu greutăți descriu gradul II (AC rupt, coracoclaviculare întinse).','Mallet se vindecă bine prin imobilizare, nu prin sutură de urgență.']],
 8,'Schimbă gradul II cu III la AC și transformă Mallet-ul conservator în urgență chirurgicală.',['gradul lll','6 săptămâni'],[608]),

q(39,['Un sportiv de vârstă mijlocie simte o lovitură în gambă; flexia plantară activă este slabă, dar prezentă. Testul Thompson fără flexie plantară la strângerea gambei indică:',
 ['Ruptura tendonului Ahilean; flexia plantară reziduală este menținută de tibialul posterior și flexorul lung al degetelor','Ruptura completă a tibialului posterior, Ahilele rămânând intact','O entorsă de gradul I a ligamentului talofibular anterior','Fractura de stres a calcaneului, vizibilă de la prima radiografie','Miozită osificantă a solearului, cu indicație de rezecție înainte de 18 luni'],'A',609,'Ruptura de tendon Ahilean — Testul Thompson',
 'Interpretarea Thompson-ului negativ (fără flexie plantară) ca ruptură de Ahile, cu PF reziduală din tibial posterior și FDL.',
 ['Absența flexiei plantare la strângerea gambei indică ruptura Ahilelui; PF activă slabă persistă prin tibial posterior și FDL.','Tibialul posterior explică PF reziduală, nu este structura ruptă.','Entorsa ATFL nu anulează testul Thompson.','Fractura de stres nu este diagnosticul acestei manevre.','Miozita osificantă se rezecează tardiv (după 18 luni), nu este diagnosticul Thompson.']],
 8,'Atribuie deficitul tibialului posterior sau entorsei laterale, ignorând complexul gastrocnemian-solear.',['Testul Thompson','tendonului lui Ahille']),

q(40,['Displazia de dezvoltare a șoldului:',
 ['Incidența este de 1,5/1.000 nou-născuți; într-o treime din cazuri este bilaterală; sexul feminin este mai afectat','Manevrele Ortolani și Barlow sunt utile în special în primele două săptămâni de viață; tratamentul precoce folosește hamul Pavlik','După vârsta de o lună, cel mai relevant semn este limitarea abducției coapsei','Capul femural este vizibil radiografic de la naștere, deci ecografia nu are rol în primele 9 luni','Manevra Barlow reduce capul în acetabul, iar Ortolani luxează șoldul instabil'],'ABC',613,'Displazia de dezvoltare a șoldului — Ortolani, Barlow, Pavlik',
 'Aplicarea epidemiologiei, a ferestrei de 2 săptămâni pentru Ortolani/Barlow și a hamului Pavlik, față de ecografia din primele 9 luni.',
 ['Incidența 1,5/1.000, treimea bilaterală și predilecția feminină sunt explicite.','Utilitatea în primele două săptămâni și hamul Pavlik sunt descrise.','Limitarea abducției după o lună este semnul cel mai relevant.','Capul este cartilaginos până la circa 9 luni; ultrasonografia este utilă în această perioadă.','Ortolani reduce (cracment de revenire), Barlow luxează prin adducție și flexie.']],
 8,'Inversează Ortolani/Barlow și înlocuiește ecografia precoce cu radiografia de la naștere.',['hamului Pavlik','semnul Barlow'],[614]),

q(41,['Boala Legg-Calvé-Perthes și epifizioliza femurală proximală:',
 ['Perthes reprezintă osteonecroza capului femural la copii de 4–8 ani, cu raport băieți/fete de 8/1','Durerea poate fi referită pe fața internă a genunchiului, în teritoriul nervului obturator','Epifizioliza este mai frecventă la băieți, bilaterală în circa 33%, la 10–14 ani, la obezi cu insuficiență gonadală sau la copii înalți cu creștere rapidă','Perthes afectează predominant fetele adolescente, cu raport 1/8 față de băieți','Epifizioliza se tratează prin ham Pavlik, fără fixare cu șuruburi'],'ABC',614,'Perthes și epifizioliza femurală proximală',
 'Contrastarea vârstei 4–8 ani și a raportului 8/1 din Perthes cu profilul 10–14 ani și 33% bilateral al epifiziolizei.',
 ['Vârsta 4–8 ani și raportul 8/1 sunt explicite.','Durerea referită pe obturator, deci investigarea șoldului la durere de genunchi, este descrisă.','Predilecția masculină, 33% bilateral, 10–14 ani și cele două biotipuri sunt enunțate.','Raportul 8/1 este masculin/feminin, nu invers, și nu privește adolescente.','Capul se fixează cu multiple șuruburi; Pavlik este tratamentul DDH.']],
 8,'Oglindește sex-ratio-ul Perthes și atribuie hamul Pavlik epifiziolizei.',['4-8 ani','aproximativ 33%']),

q(42,['Scolioza idiopatică a adolescentului se caracterizează prin:',
 ['Fetele sunt afectate de nouă ori mai frecvent decât băieții; deformarea se accentuează cel mai frecvent în adolescență','Curburile toracice severe pot compromite funcția cardio-pulmonară','Scolioza congenitală asociază frecvent malformații de tub neural, genito-urinare și cardiovasculare','Băieții sunt afectați de nouă ori mai frecvent, iar curba este dureroasă de la debut','Scolioza neuromusculară se limitează la un segment scurt, similar neurofibromatozei'],'ABC',615,'Scolioza — Idiopatică, congenitală și neuromusculară',
 'Recunoașterea predilecției feminine 9:1, a riscului cardio-pulmonar toracic și a malformațiilor asociate formei congenitale.',
 ['Raportul 9:1 fete/băieți și accentuarea în adolescență sunt explicite.','Compromiterea cardio-pulmonară a curburilor toracice severe este menționată.','Asocierea cu tub neural, GU și CV la forma congenitală este enunțată.','Predilecția este feminină; forma idiopatică este descrisă ca nedureroasă progresivă.','Curbarea neuromusculară implică de obicei întreaga lungime a coloanei; segmentul scurt sever este al neurofibromatozei.']],
 8,'Inversează sex-ratio-ul 9:1 și confundă curba lungă neuromusculară cu segmentul scurt din neurofibromatoză.',['nouă ori mai frecvent','cardio-pulmonară']),

q(43,['Osteomielita hematogenă acută la copil:',
 ['Metafizele oaselor lungi sunt cele mai obișnuite focare, prin turbulența capilarelor care se răsucesc la cartilajul de creștere','În grupa 0–3 luni sunt implicate bacterii coliforme; până la 3 ani Haemophilus influenzae; Staphylococcus aureus apare la toate vârstele','Antibioticele se continuă cel puțin 3 săptămâni; lipsa ameliorării în 24 de ore impune drenajul abcesului subperiostal','Modificările radiologice apar din prima zi și fac scintigrafia inutilă','La adult, germenul principal rămâne Escherichia coli, nu S. aureus'],'ABC',616,'Osteomielita hematogenă acută',
 'Aplicarea predilecției metafizare, a spectrului pe vârste și a ferestrelor 24 de ore/3 săptămâni.',
 ['Anatomia capilarelor metafizare și predilecția sediului sunt explicite.','Coliformele 0–3 luni, H. influenzae până la 3 ani și S. aureus la toate vârstele sunt citate.','Cele 3 săptămâni de antibiotic și drenajul după 24 de ore fără ameliorare sunt enunțate.','Modificările radiologice apar târziu, după o săptămână sau mai mult; scintigrafia în 3 faze ajută precoce.','S. aureus rămâne principala cauză a infecției osoase la adulți.']],
 8,'Anulează latența radiologică și înlocuiește S. aureus adult cu E. coli.',['bacteriile coliforme','abces subperiostal']),

q(44,['Artrita septică:',
 ['La copii apare ca o complicație a osteomielitei hematogene; articulațiile cu metafiza în capsulă sunt șoldul, cotul și umărul','Suspiciunea clinică justifică aspirația lichidului articular în urgență pentru cultură, colorație Gram și numărarea celulelor','Aspirația printr-o zonă de celulită este contraindicată, deoarece poate introduce germeni în articulație','Un număr de leucocite sub 50.000 nu este de obicei infecțios; peste 100.000 este sugestiv pentru infecție','Tratamentul de elecție este antibioterapia orală prelungită, fără artrotomie sau lavaj'],'ABCD',617,'Artrita septică — Aspirație, praguri celulare și urgență',
 'Integrarea articulațiilor cu metafiză intracapsulară, a aspirației de urgență, a interdicției prin celulită și a pragurilor 50.000/100.000.',
 ['Șoldul, cotul și umărul sunt enumerate ca articulații cu metafiză în capsulă.','Aspirația în urgență la suspiciune clinică este cerută.','Contraindicația aspirației prin celulită este explicită.','Pragurile sub 50.000 și peste 100.000 sunt citate.','Tratamentul eficient este artrotomia, drenajul, debridarea și lavajul, plus antibiotic intravenos.']],
 9,'Near-miss pe pragurile 50.000/100.000 și pe interdicția de a aspira prin celulită.',['<SO.OOO','> 100.000']),

q(45,['Tenosinovita septică a flexorilor mâinii și fasceita necrozantă:',
 ['Kanavel descrie deget edemațiat uniform, poziție flectată, durere pe teacă la presiune anteroposterioară și durere ascuțită la extensie pasivă','Absența ameliorării în 24–48 de ore impune drenaj chirurgical și lavaj abundent','Fasceita necrozantă de tip 2 este determinată de streptococ β-hemolitic de grup A, asociat sau nu cu S. aureus, la pacienți anterior sănătoși','Tipul 1 de fasceită necrozantă este monomicrobian, rezervat gazdelor imunocompetente','Rata mortalității în fasceita necrozantă este neglijabilă, sub 1%'],'ABC',618,'Tenosinovita flexorilor (Kanavel) și fasceita necrozantă',
 'Recunoașterea celor 4 semne Kanavel, a ferestrei 24–48 de ore și a tipului 2 streptococic la gazdă sănătoasă.',
 ['Cele patru semne Kanavel sunt enumerate.','Fereastra 24–48 de ore către chirurgie este explicită.','Tipul 2 streptococic, cu sau fără S. aureus, la anterior sănătoși, este descris.','Tipul 1 este polimicrobian, cel mai frecvent la imunocompromiși.','Mortalitatea se poate apropia de 25%.']],
 8,'Oglindește tipurile 1/2 de fasceită și înlocuiește mortalitatea de 25% cu sub 1%.',['Kanavel','se poate apropia de 25%']),

q(46,['Osteoartroza și artrita reumatoidă se deosebesc prin:',
 ['Radiologic, osteoartroza asociază pensare localizată a spațiului, scleroză subcondrală, osteofite și chiste subcondrale','Cartilajul articular nu are inervație; durerea din artroză are originea în structurile periarticulare','Artrita reumatoidă este mai frecventă la femei (3:1), asociată HLA-DR4; 80% au factor reumatoid, prezent însă și la 1–5% din populația generală','Osteofitele hipertrofice sunt rare în artrita reumatoidă','Artroplastia totală de genunchi reduce durerea în mai puțin de 20% din cazuri și se rezervă tinerilor foarte activi'],'ABCD',619,'Osteoartroza versus artrita reumatoidă',
 'Contrastarea celor 4 semne radiologice OA și a originii periarticulare a durerii cu profilul RA (3:1, HLA-DR4, osteofite rare).',
 ['Cele patru elemente patognomonice radiologice sunt enumerate.','Absența inervației cartilajului și originea periarticulară a durerii sunt explicite.','Raportul 3:1, HLA-DR4, 80% RF și 1–5% în populație sunt citate.','Osteofitele rare în RA sunt enunțate.','Artroplastia totală reduce durerea în peste 90% și se rezervă artrozei avansate cu stil de viață relativ sedentar.']],
 8,'Înlocuiește rata de 90% a artroplastiei cu 20% și inversează indicația tânăr activ (care este a artrodezei).',['Pensarea localizată','HLA-DR4'],[620]),

q(47,['Hernia de disc lombară și sindromul de coadă de cal:',
 ['Cele mai frecvent afectate discuri sunt L4–L5 și L5–S1; discul L4–L5 rupt afectează rădăcina L5, iar L5–S1 rădăcina S1','Testul de ridicare a membrului inferior este pozitiv prin durere radiată sub nivelul genunchiului','Hernierea centrală cu incontinență fecală și urinară (sindrom de coadă de cal) este o urgență chirurgicală','Majoritatea durerilor lombare se datorează unui disc alunecat; peste 50% necesită tratament chirurgical','Indicațiile absolute de decompresie includ doar durerea axială mecanică de peste 48 de ore'],'ABC',623,'Hernia de disc lombară — Rădăcini și coadă de cal',
 'Aplicarea corespondenței L4–L5/L5 și L5–S1/S1, a Lasegue-ului sub genunchi și a urgenței cozii de cal.',
 ['Segmentele și rădăcinile corespunzătoare sunt explicite.','Pozitivitatea prin durere sub genunchi este descrisă.','Coada de cal ca urgență pentru a evita incontinența permanentă este enunțată.','80–90% din durerile lombare au etiologie necunoscută; doar 1–2% necesită chirurgie.','Indicațiile absolute sunt deficitul neurologic progresiv și sindromul de coadă de cal.']],
 8,'Supraestimează ponderea discului alunecat și înlocuiește indicațiile absolute cu durerea axială scurtă.',['L4-L5','sindrom de coadă de cal'],[625]),

q(48,['Osteoporoza se deosebește de osteomalacie prin:',
 ['În osteoporoză, compoziția chimică este normală, dar mineralul osos total este cu peste 2 deviații standard sub etalonul de vârstă; raportul mineral/matrice rămâne normal','În osteomalacie, cantitatea de matrice pe unitatea de volum este normală, dar insuficient calcificată; raportul mineral/matrice este scăzut','Forma pediatrică a osteomalaciei se numește rahitism','Osteoporoza are matrice nemineralizată abundantă (zone osteoide largi), iar osteomalacia are raport mineral/matrice normal','Zona Looser este patognomonică osteoporozei involutive, nu osteomalaciei'],'ABC',627,'Osteoporoza versus osteomalacie',
 'Contrastarea raportului mineral/matrice normal (osteoporoză, ambele deficiente) versus scăzut (osteomalacie, mineralizare inadecvată).',
 ['Definiția cu peste 2 DS și raportul normal sunt explicite.','Matricea normală cantitativ, slab calcificată, și raportul scăzut definesc osteomalacia.','Rahitismul ca formă pediatrică este enunțat.','Zonele osteoide largi țin de osteomalacie, nu de osteoporoză.','Zona Looser (bandă de rarefiere, fractură de stres în curs de vindecare) este caracteristică osteomalaciei.']],
 8,'Oglindește raportul mineral/matrice și atribuie liniile Looser osteoporozei.',['peste 2 deviaţii standard','matricea organică'],[628]),

q(49,['Tumorile osoase primare:',
 ['Cea mai frecventă tumoră primară osoasă este mielomul multiplu; scintigrafia osoasă este negativă în mielom','Osteosarcomul este bimodal, adesea înainte de 30 de ani, metafizar; 50% interesează femurul distal și tibia proximală, cu spiculi „raze de soare”','Sarcomul Ewing apare la 10–15 ani, diafizar, cu aspect de „bulb de ceapă”, și poate fi confundat clinic și histologic cu osteomielita','Osteomul osteoid produce durere care cedează adesea la aspirină, la sub 30 de ani, femur și tibie, zonă radiotransparentă sub 1 cm cu scleroză','Tumora cu celule gigante este o leziune diafizară a copilului înainte de închiderea cartilajului de creștere, cu evoluție invariabil benignă'],'ABCD',630,'Neoplasmele osului — Mielom, osteosarcom, Ewing, osteom osteoid',
 'Recunoașterea mielomului ca cea mai frecventă tumoră primară (scintigrafie negativă), a osteosarcomului metafizar „raze de soare” și a Ewing-ului „bulb de ceapă”.',
 ['Mielomul ca cea mai frecventă primară și scintigrafia negativă sunt explicite.','Bimodalitatea, metafiza, 50% femur distal/tibie proximală și razele de soare sunt din tabelul 28-9.','Vârsta 10–15 ani, bulb de ceapă și confuzia cu osteomielita sunt citate.','Durerea cedând la aspirină, vârsta sub 30 de ani și nidusul sub 1 cm sunt descrise.','Tumora cu celule gigante este epifizară, la 20–40 de ani, după închiderea cartilajului, și trebuie tratată ca leziune malignă.']],
 8,'Mută osteoclastomul în diafiza copilului și neagă agresivitatea lui, față de celelalte entități din tabele.',['mielom multiplu','bulb de ceapă'],[631]),

q(50,['Mersul antalgic și mersul Trendelenburg se recunosc prin:',
 ['Mersul antalgic scurtează faza de sprijin pe membrul afectat și faza de balansare a membrului opus, deci lungimea pasului','Hipotonia abductorilor șoldului (fesier mijlociu și mic) permite înclinarea bazinului contralateral; compensarea prin înclinarea trunchiului ipsilateral definește mersul Trendelenburg','Faza de sprijin ocupă 60% din ciclul de mers, iar faza de balansare 40%','Mersul antalgic prelungește faza de sprijin pe membrul dureros, pentru a „testa” articulația','Mersul Trendelenburg este produs de hipotonia cvadricepsului, pacientul împingând coapsa înapoi cu mâna'],'ABC',633,'Mersul — Ciclul de mers, antalgic și Trendelenburg',
 'Contrastarea scurtării fazei de sprijin (antalgic) cu înclinarea ipsilaterală de compensare a deficitului de fesier mijlociu (Trendelenburg).',
 ['Despovărarea rapidă scurtează sprijinul pe membrul afectat și balansul opusului.','Mecanismul abductorilor și compensarea ipsilaterală sunt descrise ca mers Trendelenburg sau de tip fesier mijlociu.','Raportul 60%/40% al ciclului este explicit.','Reacția la durere este despovărarea, nu prelungirea sprijinului.','Împingerea coapsei înapoi compensează hipotonia de cvadriceps, nu mersul Trendelenburg.']],
 8,'Inversează scurtarea versus prelungirea sprijinului antalgic și atribuie Trendelenburg-ul cvadricepsului.',['60% din ciclu','mers Trendelenburg'],[632]),
];
